import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,S as c,T as l,b as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-pB8LFUv2.js";import{t as v}from"./eye-CnS8emV8.js";import{D as y}from"./index-J3P0holD.js";import{t as b}from"./CodeEditor-BZlrvoTL.js";var x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{variant:`project`,chip:e??`Блок 7 · Объектная модель`,title:`Представление и вычисляемое свойство Task`,intro:`Добавим к уже знакомой Task удобный текст для человека и вычисляемую подпись статуса. Разберём, что означает подчёркивание в имени, и исследуем getter и setter отдельно, не меняя выбранные методы модели.`,tags:[{icon:(0,x.jsx)(v,{size:14}),label:`строка для человека`},{icon:(0,x.jsx)(y,{size:14}),label:`границы доступа`}]}),(0,x.jsxs)(s,{number:`00`,title:`От состояния к представлению`,children:[(0,x.jsx)(o,{children:`В предыдущем занятии мы добавили к Task методы mark_done, rename и set_priority. Теперь можем получить её состояние по отдельным атрибутам, но при показе хочется увидеть одну понятную строку, которая не устареет после изменения задачи.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`В Task есть id, title, priority, is_done и методы, которые безопасно меняют её состояние.`},{title:`Новый вопрос`,description:`Как собрать удобную карточку и подпись статуса, не храня одно состояние дважды?`},{title:`Результат`,description:`Добавить __str__ и status_label, а на отдельном примере понять пределы property и инкапсуляции.`}]}),(0,x.jsx)(`p`,{children:`Сначала отделим строку для человека от данных, затем проследим, как статус вычисляется из is_done. После этого посмотрим, как соглашение об имени и property помогают договориться о доступе, и почему в Task остаются явные методы изменения.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Один объект может иметь разные представления`,children:[(0,x.jsx)(o,{children:`Представление отвечает на вопрос «как показать значение для этой цели?». Одна задача может быть показана человеку как короткая карточка, а храниться и обрабатываться как набор полей с определёнными типами. Смысл Task от смены показа не меняется. Имя __str__ обозначает специальный метод, который Python вызывает, когда нужен обычный текст объекта.`}),(0,x.jsx)(`p`,{children:`Представим бумажную папку с документами. Надпись на корешке помогает быстро узнать, что внутри, и её можно переписать, не перекладывая документы. Но одна надпись не содержит все страницы и не позволяет надёжно восстановить их порядок. Так же устроена строка объекта: она кратко показывает состояние, но не заменяет структуру полей. Граница аналогии в том, что строку формирует Python-вызов метода, а не человек с ручкой.`}),(0,x.jsx)(t,{rows:[[(0,x.jsx)(x.Fragment,{children:`str(task)`}),`текст, который __str__ возвращает для человека`],[(0,x.jsx)(x.Fragment,{children:`repr(task)`}),`представление для диагностики и разработчика`],[(0,x.jsx)(x.Fragment,{children:`print(task)`}),`выводит результат str(task), сам не описывает поля`],[(0,x.jsx)(x.Fragment,{children:`запись Task`}),`структура с отдельными id, title, priority и is_done`]]}),(0,x.jsx)(`p`,{children:`repr тоже возвращает строку, но обычно помогает исследовать значение в отладке. Мы не настраиваем его в этом занятии. print, напротив, выполняет вывод: когда передаём ему объект, он просит Python получить его строковое представление. Разделение важно, потому что текст карточки можно сделать удобнее для чтения, не меняя имена и типы полей, от которых зависит программа.`}),(0,x.jsx)(`p`,{children:`У разных потребителей могут быть разные требования к одному объекту. Человек хочет быстро заметить название и статус; проверка программы может отдельно обратиться к is_done; будущая запись в JSON должна сохранить поле именно как bool. Если всё свести к одной строке, потребителю придётся разбирать подписи и надеяться, что их написание не поменялось. Поэтому строка помогает читать, но не становится универсальным контейнером данных. Мы выбираем форму по задаче получателя, а не по тому, насколько коротко выглядит вызов.`}),(0,x.jsx)(l,{question:`Какой вариант задаёт результат str(task), который можно потом передать print?`,left:{title:`Вывод внутри __str__`,code:`def __str__(self):
    print(self.title)`,note:`Метод печатает побочный текст и не возвращает строку.`},right:{title:`Возврат строки из __str__`,code:`def __str__(self):
    return self.title`,note:`Вызывающий код получает значение и сам решает, где его показать.`},preferred:`right`,explanation:`Мы разделяем подготовку значения и вывод. Контракт __str__ требует вернуть str; print внутри метода возвращает None и не подменяет этот результат.`})]}),(0,x.jsxs)(s,{number:`02`,title:`__str__ возвращает карточку, собранную из Task`,children:[(0,x.jsx)(o,{children:`Когда у класса нет __str__, печать может показать техническую строку с именем класса и адресом объекта. Для Task полезнее показать те же четыре поля в привычной карточке. Метод не печатает сам: он возвращает строку, а print или другой вызывающий код решает, что делать с результатом.`}),(0,x.jsx)(`p`,{children:`Сначала посмотрим на независимый пример, чтобы увидеть только один новый механизм. Класс Notice хранит номер и короткое сообщение, а __str__ собирает из них строку. Функция print не является частью метода.`}),(0,x.jsx)(b,{caption:`небольшой независимый пример`,code:`class Notice:
    def __init__(self, number, message):
        self.number = number
        self.message = message

    def __str__(self):
        return f"Уведомление {self.number}: {self.message}"

notice = Notice(4, "Отчёт готов")
text = str(notice)
print(text)`}),(0,x.jsx)(`p`,{children:`При str(notice) Python вызывает notice.__str__() и получает строку. Мы сохраняем её в text, поэтому результат можно проверить, передать дальше или вывести. Если написать print внутри __str__ и ничего не вернуть, произойдёт два разных действия: побочный вывод и возврат None. str не сможет использовать None как строковое представление и сообщит об ошибке типа.`}),(0,x.jsx)(r,{tone:`info`,children:`__str__ должен возвращать строку. Вызов print(task) уже сам выводит её; печать внутри __str__ смешивает получение значения с побочным эффектом.`}),(0,x.jsx)(`p`,{children:`Теперь применим эту идею к модели. Сохраняем узнаваемый формат карточки прежнего Planner: id, название, приоритет и русскую подпись статуса. Каждую часть берём у того же экземпляра через self. Формат словарей для текущего CLI остаётся у его format_task; мы не меняем потребителей и не превращаем строку в формат хранения.`}),(0,x.jsx)(b,{caption:`фрагмент метода в app.models.Task`,code:`def __str__(self):
    return (
        f"[{self.id}] {self.title} | "
        f"приоритет: {self.priority} | {self.status_label}"
    )`}),(0,x.jsx)(`p`,{children:`Это добавление внутрь существующего класса, а не новый класс Task. Скобки позволяют собрать одну строку из соседних f-строк. Каждая строка возвращается как часть общего результата, а значение status_label появится после того, как мы определим свойство в следующем разделе.`}),(0,x.jsx)(`p`,{children:`Выражения в фигурных скобках f-строки читают атрибуты в момент вызова __str__. Поэтому после rename строка будет содержать новое название, а после изменения приоритета покажет новый приоритет. Мы не сохраняем прошлый текст карточки в объекте и не редактируем его при каждом переходе. Это уменьшает число копий одного значения, которые пришлось бы поддерживать согласованными.`}),(0,x.jsx)(c,{statement:(0,x.jsx)(x.Fragment,{children:`Если __str__ напечатает карточку через print, Python автоматически получит эту же карточку как возвращаемую строку.`}),isTrue:!1,explanation:`Мы не получаем строку из побочного вывода: print возвращает None. __str__ отдельно возвращает str, а внешний print показывает это значение.`})]}),(0,x.jsxs)(s,{number:`03`,title:`Вычисляемая подпись читает один источник состояния`,children:[(0,x.jsx)(o,{children:`Статус задачи уже задан булевым полем is_done. Если дополнительно хранить строку «выполнена» или второй флаг, со временем одно значение может измениться, а другое остаться старым. Вместо этого мы вычисляем подпись при чтении из текущего is_done. Так у модели остаётся один источник истины.`}),(0,x.jsx)(`p`,{children:`Представим панель с индикатором работающего устройства. Сам индикатор не является вторым независимым датчиком: он показывает результат чтения основного состояния. Здесь is_done играет роль состояния, а status_label — индикатора с понятной человеку подписью. Граница аналогии: property не измеряет физический объект и не запрещает изменить поле напрямую; она лишь вычисляет значение при чтении.`}),(0,x.jsx)(b,{caption:`фрагмент вычисляемого свойства Task`,code:`@property
def status_label(self):
    if self.is_done:
        return "выполнена"
    return "не завершена"`}),(0,x.jsx)(`p`,{children:`Декоратор @property связывает чтение имени status_label с методом. Снаружи мы пишем task.status_label, без круглых скобок, но Python выполняет этот метод и использует возвращённую строку. Значение отдельно не сохраняется. Если mark_done меняет is_done, следующее чтение сразу даст новую подпись. Само свойство ничего не завершает и не записывает в JSON.`}),(0,x.jsx)(`p`,{children:`Внутри класса у метода всё равно остаётся параметр self: он показывает, у какого экземпляра мы читаем is_done. Метод свойства не принимает отдельный status и не ищет задачу в общем списке. Условия возвращают обычные строки для двух допустимых состояний, а не преобразуют произвольное значение в bool. Если поле испорчено внешним присваиванием, property не исправит его автоматически. Это вычисляемая подпись, не валидатор и не защита каждой записи.`}),(0,x.jsx)(g,{caption:`Как текущее состояние превращается в строку для человека`,children:(0,x.jsxs)(m,{label:`От состояния Task к вызывающему коду`,children:[(0,x.jsx)(f,{title:`is_done`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Хранит bool конкретной задачи`})}),(0,x.jsx)(p,{label:`property читает`}),(0,x.jsx)(f,{title:`status_label`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Возвращает русскую подпись`})}),(0,x.jsx)(p,{label:`__str__ включает`}),(0,x.jsx)(f,{title:`строка Task`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Собирает поля в карточку`})}),(0,x.jsx)(p,{label:`str(task) получает`}),(0,x.jsx)(f,{title:`вызывающий код`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Показывает или использует текст`})})]})}),(0,x.jsx)(`p`,{children:`Читаем схему слева направо: Task хранит bool, property переводит его в подпись, __str__ включает подпись в карточку, а str(task) возвращает её вызывающему коду. Стрелки показывают передачу результата, а не запись новых полей. Тот же порядок важен после mark_done: повторно собранная строка отражает уже обновлённое состояние.`}),(0,x.jsx)(_,{code:`task = Task(8, "Проверить отчёт", 4)
print(task.status_label)
task.mark_done()
print(task.status_label)
print(task)`,steps:[{line:0,note:`Мы создаём Task с is_done=False.`,vars:{"task.is_done":`False`}},{line:1,note:`Мы читаем свойство; оно возвращает подпись из текущего bool.`,vars:{вывод:`не завершена`}},{line:2,note:`Мы вызываем уже знакомый метод, который меняет состояние Task.`,vars:{"task.is_done":`True`}},{line:3,note:`При новом чтении property вычисляет подпись заново.`,vars:{вывод:`выполнена`}},{line:4,note:`Мы получаем карточку, собранную __str__ из актуальных полей.`,vars:{вывод:`[8] Проверить отчёт | приоритет: 4 | выполнена`}}]}),(0,x.jsx)(`p`,{children:`В строке вызова свойства нет скобок, потому что по договору это чтение. А mark_done вызывается как метод действия. Property не возвращает новый Task: оно даёт только подпись. Если нужен список задач или файл, этот объект не становится их владельцем.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Инкапсуляция задаёт соглашение, а не замок`,children:[(0,x.jsx)(o,{children:`В Python одно подчёркивание в начале имени, например _priority, сообщает другим разработчикам: это внутренняя деталь класса, и обычный внешний код не должен менять её без причины. Язык не запрещает обращаться к такому атрибуту. Поэтому корректное состояние зависит от ясного интерфейса и соблюдения договорённости, а не от магической защиты имени.`}),(0,x.jsx)(`p`,{children:`Это похоже на табличку «служебная дверь»: она указывает, как принято пользоваться помещением, но сама не запирает ручку. Здесь _priority — знак для читателя кода, а не барьер Python. Аналогия заканчивается тем, что доступность атрибута определяется правилами языка, а не физической дверью.`}),(0,x.jsx)(c,{statement:(0,x.jsx)(x.Fragment,{children:`Запись task._priority = 9 завершится отказом только потому, что имя начинается с одного подчёркивания.`}),isTrue:!1,explanation:`Мы трактуем подчёркивание как соглашение. Python технически позволяет прямое присваивание; код должен следовать публичному договору модели.`}),(0,x.jsx)(`p`,{children:`Property может предоставить обычный синтаксис чтения атрибута и, если объявлен setter, перехватить присваивание этому свойству. Getter отвечает за чтение, setter — за путь записи через соответствующее имя. Проверку нового значения нужно выполнить до записи: если сначала заменить внутреннее поле, а затем поднять ValueError, старое значение не восстановится само.`}),(0,x.jsx)(b,{caption:`полный отдельный пример getter и setter`,code:`class Label:
    def __init__(self, value):
        self._value = value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        cleaned = new_value.strip()
        if not cleaned:
            raise ValueError("Метка не может быть пустой")
        self._value = cleaned`}),(0,x.jsx)(`p`,{children:`Оба метода относятся к одному публичному имени value. При чтении label.value выполняется getter; при записи label.value = "Новая метка" выполняется setter. Setter сначала готовит и проверяет очищенную строку, а только потом меняет _value. Начальное значение в примере известно как корректное; конструктор не является темой этой демонстрации.`}),(0,x.jsx)(`p`,{children:`Запись выглядит как присваивание атрибуту, хотя под этим именем выполняется дополнительный код. Это удобно, когда операция естественно воспринимается как присвоение значения и для неё нужно централизованное правило. Но синтаксис может скрыть эффект от читателя. Явный метод set_priority сразу называет действие; setter свойства priority оставляет форму task.priority = value и вызывает проверку за ней. Выбор влияет на то, насколько очевидно место изменения, а не на то, существует ли проверка.`}),(0,x.jsx)(n,{code:`class Label:
    def __init__(self, value):
        self._value = value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value.strip()
        if not self._value:
            raise ValueError("Метка не может быть пустой")`,question:`Почему после отказа поле уже может содержать пустую строку?`,options:[`Мы присвоили новое значение до проверки и исключение не откатывает присваивание`,`Getter автоматически удаляет значение при ValueError`,`Одно подчёркивание запрещает читать прежнее значение`],correctIndex:0,explanation:`Мы сначала сохраняем очищенную строку, поэтому при пустом результате объект уже изменён. Сначала нужно проверить локальное cleaned, затем присвоить его внутреннему полю.`,fix:`class Label:
    def __init__(self, value):
        self._value = value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        cleaned = new_value.strip()
        if not cleaned:
            raise ValueError("Метка не может быть пустой")
        self._value = cleaned`}),(0,x.jsx)(r,{tone:`warn`,children:`Setter управляет присваиванием через label.value. Он не контролирует изменение _value напрямую и не перехватывает каждую возможную мутацию вложенного объекта.`}),(0,x.jsx)(`p`,{children:`Если setter сначала меняет поле и только потом обнаруживает ошибку, перехваченный ValueError не отменит первое присваивание. Python не сохраняет автоматическую копию предыдущего состояния для отката. Локальная переменная cleaned здесь безопасна: пока проверка не прошла, объект не менялся. Так мы переносим в setter уже знакомый принцип методов Task: сначала проверить значение, затем совершить изменение.`})]}),(0,x.jsxs)(s,{number:`05`,title:`В Task остаются явные методы изменения`,children:[(0,x.jsx)(o,{children:`У Task уже есть методы rename и set_priority, которые выражают предметные действия и используют общие валидаторы. Мы оставляем их интерфейс. В этом шаге property нужен для вычисляемого чтения status_label, а не для обязательного переписывания всех способов изменения. Так подготовленная модель останется готовой к следующему шагу — явным преобразованиям между Task и словарём.`}),(0,x.jsx)(t,{rows:[[(0,x.jsx)(x.Fragment,{children:`task.rename(title)`}),`явное действие: проверить и изменить название`],[(0,x.jsx)(x.Fragment,{children:`task.set_priority(value)`}),`явное действие: проверить и изменить приоритет`],[(0,x.jsx)(x.Fragment,{children:`task.status_label`}),`вычисляемое чтение из is_done без записи`],[(0,x.jsx)(x.Fragment,{children:`str(task)`}),`получить строку для человека, не словарь хранения`]]}),(0,x.jsx)(`p`,{children:`Если в отдельной модели установить setter для priority, запись task.priority = value станет сокращённым интерфейсом, который выполняет проверку. Но для основной Task сейчас оставляем именованные методы: их вызовы ясно обозначают действие и уже соответствуют предыдущему шагу. Мы не добавляем к классу скрытый setter, не меняем его поля на underscore и не обещаем, что прямое присваивание is_done пройдёт через mark_done.`}),(0,x.jsx)(`p`,{children:`Явное имя метода также оставляет место для предметного договора. rename может нормализовать новое название, set_priority может проверить диапазон, а mark_done обозначает устойчивый переход к выполненному состоянию. У каждого вызова виден смысл, и все они меняют одну задачу. Property в этом занятии решает другой вопрос: удобно прочитать вычисленное значение. Мы не используем его ради модного синтаксиса и не переносим setter из маленького примера в модель без необходимости.`}),(0,x.jsx)(h,{prompt:`Соединим выражение с его ролью в модели и программе.`,leftTitle:`Выражение`,rightTitle:`Роль`,pairs:[{left:`task.status_label`,right:`вычислить подпись при чтении`},{left:`task.mark_done()`,right:`изменить состояние одной Task`},{left:`str(task)`,right:`получить строку для человека`},{left:`format_task(record)`,right:`отформатировать словарную запись CLI`}],explanation:`Мы выбираем выражение по потребителю: свойство читает состояние модели, метод выполняет действие, строка удобна человеку, а старый форматтер по-прежнему получает словарь.`}),(0,x.jsx)(`p`,{children:`Новая строка не заставляет старый CLI перестать работать со словарями. Пока модель только подготавливается, словарные операции и format_task сохраняют собственный путь. В следующем занятии мы добавим явные преобразования между Task и словарём; ни __str__, ни repr для восстановления использовать нельзя.`}),(0,x.jsx)(u,{question:`Что произойдёт с status_label после уже знакомого mark_done()?`,options:[`При следующем чтении свойство вычислит подпись из нового is_done`,`Старая строка навсегда останется в отдельном поле`,`Task автоматически перезапишет JSON-файл`],correctIndex:0,explanation:`Мы не храним status_label отдельно: getter читает актуальное поле при каждом обращении.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Используем Task из app.models с её четырьмя полями, общими валидаторами и методами изменения. Готовый результат добавляет только представление и вычисляемое чтение, а getter и setter остаются отдельным небольшим исследованием.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Добавим представление`,description:`__str__ соберёт карточку из id, title, priority и вычисляемого status_label.`},{title:`Проверим изменение состояния`,description:`После mark_done строка покажет актуальный статус, а второй объект и старый CLI останутся независимыми.`},{title:`Исследуем границу setter`,description:`На отдельном классе проверим новое значение до присваивания и увидим, что остаётся прежнее при отказе.`},{title:`Разделим представления`,description:`Объясним, почему строка для человека не заменяет структурированную запись для следующего шага.`}]}),(0,x.jsx)(`p`,{children:`Эти действия опираются на уже написанные поля и методы Task. Мы подтвердим связь подписи с is_done, проверим старый форматтер на прежнем словарном пути и зафиксируем границу: модель пока не меняет весь CLI и не сохраняет новый формат. Это подготовит явную работу со словарём в следующем занятии.`})]})]})}export{S as Lesson37_1};